    let workflow = minimal_workflow()?;

    // Seed counter to u64::MAX - 1.
    let near_max = u64::MAX
        .checked_sub(1)
        .ok_or_else(|| "u64::MAX - 1 underflow".to_string())?;
    journal
        .artifact_acceptance
        .insert(b"last_issued", &near_max.to_be_bytes())
        .map_err(|e| format!("insert counter failed: {e}"))?;

