        .map_err(|e| format!("valid workflow submission failed: {e}"))?;
    if artifact.accepted_at_seq.get() != 1 {
        return Err(format!(
            "valid workflow should get seq 1, got {}",
            artifact.accepted_at_seq.get()
        ));
    }
