        .map_err(|e| format!("retry submission failed: {e}"))?;
    if artifact.accepted_at_seq.get() != 1 {
        return Err(format!(
            "retry artifact should have seq 1, got {}",
            artifact.accepted_at_seq.get()
        ));
    }
    Ok(())
}

