    parts.digest = vb_core::WorkflowDigest::from_bytes([0xFF; 32]);
    let invalid = vb_core::CompiledWorkflow::try_from_parts(parts)
        .map_err(|e| format!("expected forged-digest workflow to reconstruct, got: {e}"))?;

