/// Shared helper: read counter value or report error/absent.
fn counter_value(journal: &crate::FjallJournal) -> Result<Option<u64>, String> {
    let raw = journal
        .artifact_acceptance
        .get(b"last_issued")
        .map_err(|e| format!("counter read failed: {e}"))?;
    match raw {
        None => Ok(None),
        Some(slice) => {
